import React, { useState, useEffect } from "react";
import Login from "./components/Login";
import Form from "./components/Form";
import IncidentList from "./components/ListaIncidencias";
import { jwtDecode } from "jwt-decode";

const API_URL = "http://localhost:3004";

function App() {
  const [usuarioLogueado, setUsuarioLogueado] = useState(null);
  const [usuarios, setUsuarios] = useState([]);
  const [incidencias, setIncidencias] = useState([]);

  // ---------------------------
  // Cargar usuarios desde API
  // ---------------------------
  useEffect(() => {
    fetch(`${API_URL}/users`)
      .then((res) => res.json())
      .then((data) => setUsuarios(data));
  }, []);

  // ---------------------------
  // Cargar incidencias desde API
  // ---------------------------
  useEffect(() => {
    fetch(`${API_URL}/incidencias`)
      .then((res) => res.json())
      .then((data) => setIncidencias(data));
  }, []);

  // ---------------------------
  // Persistencia de sesión
  // ---------------------------
  useEffect(() => {
    const savedToken = localStorage.getItem("authToken");
    if (savedToken && usuarios.length > 0) {
      const decoded = jwtDecode(savedToken);
      const user = usuarios.find((u) => u.email === decoded.email);
      if (user) setUsuarioLogueado(user);
    }
  }, [usuarios]);

  // ---------------------------
  // LOGIN
  // ---------------------------
  const onLogin = async (email, password) => {
  const response = await fetch(LOGIN_API_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });

  if (response.ok) {
    const data = await response.json();
    setUsuarioLogueado(data.user);
  } else {
    const errorData = await response.json();
    alert(`Fallo de autenticación. Error: ${response.status}: ${errorData}`);
  }
};


  // ---------------------------
  // LOGOUT
  // ---------------------------
  const logout = () => {
    localStorage.removeItem("authToken");
    setUsuarioLogueado(null);
  };

  // ---------------------------
  // CREAR INCIDENCIA (POST)
  // ---------------------------
  const agregarIncidencia = async (titulo, descripcion, email, categoria, nivel, ubicacion) => {
    const usuarioEncontrado = usuarios.find((u) => u.email === email);

    if (!usuarioEncontrado) {
      alert("Usuario no encontrado. Regístrese primero.");
      return;
    }

    const fecha = new Date().toISOString().split("T")[0];

    const nuevaIncidencia = {
      titulo,
      descripcion,
      usuario: usuarioEncontrado,
      categoria,
      nivel_urgencia: nivel,
      ubicacion,
      estado: "Abierta",
      fecha_registro: fecha,
      comentarios: []
    };

    const response = await fetch(`${API_URL}/incidencias`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(nuevaIncidencia),
    });

    if (response.ok) {
      const creada = await response.json();
      setIncidencias([...incidencias, creada]);
    }
  };

  // ---------------------------
  // RENDER
  // ---------------------------
  return (
    <div className="container mt-4">

      <h1 className="text-center mb-4">Mi aplicación de incidencias</h1>

      return (
  <>
    {!usuarioLogueado ? (
      <aside>
        <Login onLogin={onLogin} />
      </aside>
    ) : (
      <>
        <main>
          <ListadoIncidencias />
        </main>

        <aside>
          <FormularioIncidencias />
        </aside>
      </>
    )}
  </>
);
    </div>
  );
}

export default App;
